import hashlib
import heapq
import json
import math
import re
from datetime import date
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

MODEL = 'city-forge-sumo-0.1.2'
HORIZON = 900


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False, allow_nan=False)


def digest(value):
    return hashlib.sha256(canonical(value).encode()).hexdigest()


def validate(data):
    if not isinstance(data, dict):
        raise ValueError('Datová sada musí být objekt')
    for key in ('name', 'source', 'license', 'valid_on', 'timezone', 'crs'):
        if not isinstance(data.get(key), str) or not 1 <= len(data[key]) <= 200:
            raise ValueError('Chybí metadata: ' + key)
    date.fromisoformat(data['valid_on'])
    try:
        ZoneInfo(data['timezone'])
    except (ZoneInfoNotFoundError, ValueError):
        raise ValueError('Neplatné časové pásmo') from None
    if data['crs'] != 'LOCAL_METRES':
        raise ValueError('Pilot podporuje pouze LOCAL_METRES')
    nodes, edges = data.get('nodes'), data.get('edges')
    if not isinstance(nodes, list) or not 2 <= len(nodes) <= 100:
        raise ValueError('Počet uzlů musí být 2–100')
    if not isinstance(edges, list) or not 1 <= len(edges) <= 250:
        raise ValueError('Počet úseků musí být 1–250')
    def ident(value):
        return isinstance(value, str) and re.fullmatch(r'[A-Za-z][A-Za-z0-9_]{0,39}', value)
    def number(v, lo, hi):
        return type(v) in (int, float) and math.isfinite(v) and lo <= v <= hi
    ids, positions = set(), set()
    for n in nodes:
        if not isinstance(n, dict) or not ident(n.get('id')) or n['id'] in ids:
            raise ValueError('Neplatné nebo duplicitní ID uzlu')
        if not number(n.get('x'), -10000, 10000) or not number(n.get('y'), -10000, 10000):
            raise ValueError('Neplatné souřadnice')
        pos = (n['x'], n['y'])
        if pos in positions:
            raise ValueError('Dva uzly mají stejné souřadnice')
        ids.add(n['id']); positions.add(pos)
    seen, directions = set(), set()
    by_id = {n['id']: n for n in nodes}
    for e in edges:
        if not isinstance(e, dict) or not ident(e.get('id')) or e['id'] in seen:
            raise ValueError('Neplatné nebo duplicitní ID úseku')
        if not ident(e.get('source')) or not ident(e.get('target')) or e['source'] not in ids or e['target'] not in ids or e['source'] == e['target']:
            raise ValueError('Neplatný směr nebo konec úseku')
        direction = (e['source'], e['target'])
        if direction in directions:
            raise ValueError('Duplicitní orientovaný úsek')
        a, b = by_id[e['source']], by_id[e['target']]
        if math.hypot(a['x']-b['x'], a['y']-b['y']) < 20:
            raise ValueError('Úsek musí mít alespoň 20 metrů')
        if not number(e.get('speed'), 2, 35):
            raise ValueError('Rychlost musí být 2–35 m/s')
        seen.add(e['id']); directions.add(direction)
    if not ident(data.get('origin')) or not ident(data.get('hospital')) or data['origin'] not in ids or data['hospital'] not in ids or data['origin'] == data['hospital']:
        raise ValueError('Neplatný počátek nebo nemocnice')
    if type(data.get('cars')) is not int or not 0 <= data['cars'] <= 600:
        raise ValueError('Poptávka musí být 0–600 vozidel')
    buses = data.get('bus_departures')
    if not isinstance(buses, list) or len(buses) > 40 or any(not number(t, 0, 899) for t in buses):
        raise ValueError('Neplatné odjezdy autobusů')
    if buses != sorted(set(buses)):
        raise ValueError('Odjezdy musí být jedinečné a seřazené')
    if not shortest(data, None)[0]:
        raise ValueError('Nemocnice není ve výchozí síti dosažitelná')
    reached = {data['origin']}
    for _ in nodes:
        reached.update([e['target'] for e in edges if e['source'] in reached])
    if reached != ids:
        raise ValueError('Síť obsahuje nedosažitelné uzly')
    return json.loads(canonical(data))


def shortest(data, closed):
    nodes = {n['id']: n for n in data['nodes']}
    queue = [(0.0, data['origin'], [])]
    visited = set()
    while queue:
        cost, node, route = heapq.heappop(queue)
        if node in visited:
            continue
        visited.add(node)
        if node == data['hospital']:
            return route, cost
        for e in data['edges']:
            if e['source'] != node or e['id'] == closed:
                continue
            a, b = nodes[node], nodes[e['target']]
            length = math.hypot(a['x']-b['x'], a['y']-b['y'])
            heapq.heappush(queue, (cost + length/e['speed'], e['target'], route + [e['id']]))
    return [], None

import csv
import io
import json
import os
import random
import re
import signal
import subprocess
import threading
import time
import xml.etree.ElementTree as ET
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
from uuid import uuid4
from .model import MODEL, HORIZON, canonical, digest, shortest
from .tools import executable, versions


class Cancelled(Exception):
    pass


def command(args, folder, cancel, timeout=50):
    if cancel.is_set():
        raise Cancelled()
    target = executable(args[0]) if args[0] in ('sumo', 'netconvert') else args[0]
    argv = [executable('prlimit'), '--as=1610612736', '--cpu=45', '--fsize=33554432', '--', target, *args[1:]]
    with open(folder / 'process.log', 'ab') as log:
        proc = subprocess.Popen(argv, cwd=folder, stdout=log, stderr=log, start_new_session=True)
        deadline = time.monotonic() + timeout
        try:
            while proc.poll() is None:
                if cancel.wait(0.05):
                    raise Cancelled()
                if time.monotonic() > deadline:
                    raise RuntimeError('Překročen limit času procesu')
            if cancel.is_set():
                raise Cancelled()
            if proc.returncode:
                tail = (folder / 'process.log').read_text(errors='replace')[-2000:]
                raise RuntimeError('SUMO/netconvert selhal: ' + tail)
        finally:
            if proc.poll() is None:
                try:
                    os.killpg(proc.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                proc.wait()


def xmlwrite(path, root):
    ET.ElementTree(root).write(path, encoding='utf-8', xml_declaration=True)


def simulate(data, closed, seed, factor, folder, cancel):
    if cancel.is_set():
        raise Cancelled()
    folder.mkdir(parents=True, exist_ok=True)
    route, hospital = shortest(data, closed)
    rng = random.Random(seed)
    departures = [(rng.uniform(0, 600), 'car', f'c{i}') for i in range(round(data['cars']*factor))]
    departures += [(t, 'bus', f'b{i}') for i, t in enumerate(data['bus_departures'])]
    departures.sort()
    requested = len(departures)
    if not route:
        return {'travel_s': None, 'bus_s': None, 'waiting_s': None, 'max_queue_m': None,
                'completed': 0, 'unreachable': requested, 'unfinished': 0,
                'hospital_freeflow_s': None, 'edge_entries': {}, 'route': []}
    nodes = ET.Element('nodes')
    for n in data['nodes']:
        ET.SubElement(nodes, 'node', id=n['id'], x=str(n['x']), y=str(n['y']), type='priority')
    edges = ET.Element('edges')
    for e in data['edges']:
        ET.SubElement(edges, 'edge', id=e['id'], **{'from': e['source'], 'to': e['target']},
                      speed=str(e['speed']), numLanes='1', priority='1')
    xmlwrite(folder / 'nodes.xml', nodes); xmlwrite(folder / 'edges.xml', edges)
    command(['netconvert', '--node-files', 'nodes.xml', '--edge-files', 'edges.xml',
             '--output-file', 'net.xml', '--no-turnarounds', 'true'], folder, cancel)
    routes = ET.Element('routes')
    ET.SubElement(routes, 'vType', id='car', vClass='passenger', sigma='0.5')
    ET.SubElement(routes, 'vType', id='bus', vClass='bus', length='12', accel='1.2', sigma='0.5')
    ET.SubElement(routes, 'route', id='chosen', edges=' '.join(route))
    for depart, kind, ident in departures:
        ET.SubElement(routes, 'vehicle', id=ident, type=kind, route='chosen',
                      depart=f'{depart:.3f}', departLane='best', departSpeed='0')
    xmlwrite(folder / 'routes.xml', routes)
    additional = ET.Element('additional')
    ET.SubElement(additional, 'edgeData', id='counts', file='edges-out.xml', begin='0', end=str(HORIZON))
    xmlwrite(folder / 'additional.xml', additional)
    command(['sumo', '--net-file', 'net.xml', '--route-files', 'routes.xml',
             '--additional-files', 'additional.xml', '--seed', str(seed), '--end', str(HORIZON),
             '--tripinfo-output', 'trips.xml', '--queue-output', 'queues.xml',
             '--time-to-teleport', '-1', '--no-step-log', 'true',
             '--duration-log.disable', 'true', '--xml-validation', 'never'], folder, cancel)
    trips = list(ET.parse(folder / 'trips.xml').getroot())
    cars = [float(t.attrib['duration']) for t in trips if t.attrib.get('vType') == 'car']
    buses = [float(t.attrib['duration']) for t in trips if t.attrib.get('vType') == 'bus']
    waits = [float(t.attrib['waitingTime']) for t in trips]
    queues = [float(l.attrib['queueing_length']) for l in ET.parse(folder / 'queues.xml').iter('lane')]
    entries = {e.attrib['id']: int(e.attrib.get('entered', '0')) + int(e.attrib.get('departed', '0'))
               for e in ET.parse(folder / 'edges-out.xml').iter('edge')}
    if closed and entries.get(closed, 0):
        raise RuntimeError('Porušení invariantu: průjezd uzavřeným úsekem')
    mean = lambda values: sum(values)/len(values) if values else None
    return {'travel_s': mean(cars), 'bus_s': mean(buses), 'waiting_s': mean(waits),
            'max_queue_m': max(queues, default=0), 'completed': len(trips), 'unreachable': 0,
            'unfinished': requested-len(trips), 'hospital_freeflow_s': hospital,
            'edge_entries': entries, 'route': route}


class Manager:
    def __init__(self, root):
        self.root = Path(root); self.root.mkdir(parents=True, exist_ok=True)
        self.pool = ThreadPoolExecutor(max_workers=1)
        self.lock = threading.RLock()
        self.jobs, self.events = {}, {}
        for path in self.root.glob('*/job.json'):
            try:
                job = json.loads(path.read_text())
                if not re.fullmatch('[a-f0-9]{32}', job['id']) or path.parent.name != job['id']:
                    continue
                if job['status'] in ('running', 'queued', 'cancelling'):
                    job.update(status='failed', error='Předchozí proces byl přerušen', results=[])
                    self.save(job)
                self.jobs[job['id']] = job
            except (ValueError, KeyError, TypeError, OSError):
                continue

    def save(self, job):
        folder = self.root / job['id']; folder.mkdir(exist_ok=True)
        tmp = folder / 'job.tmp'
        tmp.write_text(canonical(job), encoding='utf8')
        tmp.replace(folder / 'job.json')

    def submit(self, data, closed, seeds, factor):
        with self.lock:
            if len(self.jobs) >= 20:
                raise ValueError('Limit 20 uložených běhů. Při zavřené aplikaci archivujte datový adresář.')
            if any(j['status'] in ('queued', 'running', 'cancelling') for j in self.jobs.values()):
                raise ValueError('Již probíhá výpočet nebo jeho rušení')
            ident = uuid4().hex
            snapshot = json.loads(canonical(data))
            job = {'id': ident, 'status': 'queued', 'dataset': snapshot, 'input_sha256': digest(snapshot),
                   'model': MODEL, 'closed': closed, 'seeds': list(seeds), 'factor': factor,
                   'horizon_s': HORIZON, 'results': [], 'error': None}
            self.jobs[ident] = job; self.events[ident] = threading.Event(); self.save(job)
            self.pool.submit(self.work, ident)
            return self.get(ident)

    def get(self, ident):
        with self.lock:
            return json.loads(canonical(self.jobs[ident]))

    def cancel(self, ident):
        with self.lock:
            job = self.jobs[ident]
            if job['status'] in ('queued', 'running'):
                self.events[ident].set()
                job['status'] = 'cancelling'; self.save(job)
            return self.get(ident)

    def work(self, ident):
        job, event = self.jobs[ident], self.events[ident]
        try:
            with self.lock:
                if event.is_set():
                    raise Cancelled()
                job['status'] = 'running'; self.save(job)
            tool_versions = versions()
            results = []
            for seed in job['seeds']:
                pair = {'seed': seed}
                for label, closed in [('baseline', None), ('variant', job['closed'])]:
                    pair[label] = simulate(job['dataset'], closed, seed, job['factor'], self.root/ident/f'{seed}-{label}', event)
                results.append(pair)
            with self.lock:
                if event.is_set():
                    raise Cancelled()
                job.update(status='completed', results=results, **tool_versions)
                job['scenario_sha256'] = digest({k: job[k] for k in ('input_sha256', 'model', 'closed', 'seeds', 'factor', 'horizon_s', 'sumo_version', 'netconvert_version', 'prlimit_version')})
                self.save(job)
        except Exception as exc:
            with self.lock:
                job.update(status='cancelled' if isinstance(exc, Cancelled) else 'failed',
                           error=None if isinstance(exc, Cancelled) else str(exc), results=[])
                self.save(job)

    def close(self):
        with self.lock:
            for event in self.events.values():
                event.set()
        self.pool.shutdown(wait=True)


def csv_report(job):
    stream = io.StringIO(); writer = csv.writer(stream)
    keys = ['travel_s', 'bus_s', 'waiting_s', 'max_queue_m', 'completed', 'unreachable', 'unfinished', 'hospital_freeflow_s']
    writer.writerow(['input_sha256', 'scenario_sha256', 'seed', 'scenario'] + keys)
    for pair in job['results']:
        for label in ('baseline', 'variant'):
            writer.writerow([job['input_sha256'], job['scenario_sha256'], pair['seed'], label] + [pair[label][k] for k in keys])
    return stream.getvalue()

import html
import json
import os
import secrets
import socket
from contextlib import asynccontextmanager
from pathlib import Path
from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import Response
from .engine import Manager, csv_report
from .model import canonical, validate
from .tools import versions


def create_app(root, token):
    manager = Manager(root)
    @asynccontextmanager
    async def lifespan(app):
        try:
            yield
        finally:
            manager.close()
    app = FastAPI(lifespan=lifespan, docs_url=None, redoc_url=None, openapi_url=None)
    app.state.manager = manager
    dataset_path = Path(root) / 'dataset.json'
    app.state.dataset = validate(json.loads((dataset_path if dataset_path.exists() else Path(__file__).with_name('demo.json')).read_text()))

    @app.middleware('http')
    async def protect(request: Request, call_next):
        if not secrets.compare_digest(request.headers.get('X-City-Token', ''), token):
            return Response('Unauthorized', status_code=401)
        if request.method in ('PUT', 'POST'):
            total, chunks = 0, []
            async for chunk in request.stream():
                total += len(chunk)
                if total > 262144:
                    return Response('Limit těla je 256 KiB', status_code=413)
                chunks.append(chunk)
            request._body = b''.join(chunks)
        return await call_next(request)

    @app.get('/health')
    def health():
        return {'ok': True}

    @app.get('/dataset')
    def get_dataset():
        return app.state.dataset

    @app.put('/dataset')
    async def put_dataset(request: Request):
        try:
            data = validate(await request.json())
        except (ValueError, TypeError, KeyError) as exc:
            raise HTTPException(422, str(exc)) from None
        tmp = dataset_path.with_suffix('.tmp')
        tmp.write_text(canonical(data), encoding='utf8'); tmp.replace(dataset_path)
        app.state.dataset = data
        return data

    @app.post('/jobs')
    async def start(request: Request):
        try:
            body = await request.json()
            closed, seeds, factor = body['closed'], body['seeds'], body['factor']
            if not isinstance(closed, str) or closed not in {e['id'] for e in app.state.dataset['edges']}:
                raise ValueError('Neznámý úsek')
            if not isinstance(seeds, list) or not 1 <= len(seeds) <= 3 or any(type(s) is not int or not 0 <= s <= 1000000 for s in seeds) or len(set(seeds)) != len(seeds):
                raise ValueError('Zadejte 1–3 různá celočíselná semínka 0–1000000')
            if type(factor) not in (float, int) or not 0.5 <= factor <= 1.5:
                raise ValueError('Násobek poptávky musí být 0.5–1.5')
            return manager.submit(app.state.dataset, closed, seeds, factor)
        except (ValueError, KeyError, TypeError) as exc:
            raise HTTPException(422, str(exc)) from None

    def lookup(ident):
        try:
            return manager.get(ident)
        except KeyError:
            raise HTTPException(404, 'Běh neexistuje') from None

    @app.get('/jobs/{ident}')
    def job(ident: str):
        return lookup(ident)

    @app.post('/jobs/{ident}/cancel')
    def cancel(ident: str):
        lookup(ident)
        return manager.cancel(ident)

    @app.get('/jobs/{ident}/export/{fmt}')
    def export(ident: str, fmt: str):
        job = lookup(ident)
        if job['status'] != 'completed':
            raise HTTPException(409, 'Běh není dokončen')
        if fmt == 'csv':
            return Response(csv_report(job), media_type='text/csv; charset=utf-8')
        if fmt != 'html':
            raise HTTPException(404)
        report = '<!doctype html><html lang="cs"><meta charset="utf-8"><title>CITY FORGE</title><h1>CITY FORGE — nekalibrovaná demonstrace</h1><p>Uzavírka: 0–900 s. Nemocnice: volná cesta bez kolon, přednosti a výjezdu posádky. Není určeno pro operační rozhodování. Rozptyl semínek není interval spolehlivosti. Průměry jízd a stání zahrnují jen dokončená vozidla.</p><pre>' + html.escape(json.dumps(job, ensure_ascii=False, indent=2)) + '</pre></html>'
        return Response(report, media_type='text/html; charset=utf-8')
    return app


